code.code:
CREATE TABLE daftar (
  id bigint PRIMARY KEY,
  nama text NOT NULL
);

CREATE TABLE tugas (
  id bigint PRIMARY KEY,
  daftar_id bigint REFERENCES daftar (id),
  judul text NOT NULL
);

